INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Brauche ich hier eine zentrale Steuerung für jeden Bereich?', 2, '[{"text": "Nein", "correct": true, "because": "Bereiche sind eigenständig"}, {"text": "Ja", "correct": false, "because": "Dezentral organisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer trägt die Verantwortung für den Erfolg eines Geschäftsbereichs?', 3, '[{"text": "Divisionsleiter", "correct": true, "because": "Führt den Bereich"}, {"text": "Zentrales Management", "correct": false, "because": "Weniger direkter Einfluss"}, {"text": "Projektteam", "correct": false, "because": "Bereichsübergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen diese Struktur flexibel?', 5, '[{"text": "Selbstständige Bereiche", "correct": true, "because": "Eigene Entscheidungen"}, {"text": "Produktorientierung", "correct": true, "because": "Marktanpassung"}, {"text": "Zentrale Kontrolle", "correct": false, "because": "Dezentralisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Jeder Bereich hat eigene Ressourcen. b) Zentrale Teams steuern alles.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zentrale Steuerung minimal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was übersehe ich, wenn ich diese Struktur nutze?', 4, '[{"text": "Bereichsautonomie", "correct": false, "because": "Kern der Struktur"}, {"text": "Produktlinien", "correct": false, "because": "Basis der Aufteilung"}, {"text": "Zentrale Einheitlichkeit", "correct": true, "because": "Bereiche unterschiedlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob hier alle Bereiche gleich groß sind?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig vom Geschäft"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Größen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Produktlinie in dieser Struktur?', 3, '[{"text": "Aufteilungskriterium", "correct": true, "because": "Bereiche nach Produkten"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Dezentral organisiert"}, {"text": "Nebensache", "correct": false, "because": "Kern der Organisation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet diese Struktur für Innovation?', 5, '[{"text": "Bereichsspezifische Lösungen", "correct": true, "because": "Fokus auf Produkte"}, {"text": "Selbstständige Teams", "correct": true, "because": "Eigene Ideen"}, {"text": "Einheitliche Innovation", "correct": false, "because": "Bereichsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bereiche haben eigene Budgets. b) Alles wird zentral finanziert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dezentrale Budgets üblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Bereichsleiter", "correct": false, "because": "Führen die Divisionen"}, {"text": "Produktlinien", "correct": false, "because": "Basis der Struktur"}, {"text": "Zentrale Vorgaben", "correct": true, "because": "Eigenständigkeit zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Arbeiten Bereiche hier isoliert?', 2, '[{"text": "Ja", "correct": true, "because": "Wenig Querkoordination"}, {"text": "Nein", "correct": false, "because": "Kooperation nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente fördern die Selbstständigkeit?', 4, '[{"text": "Eigene Führung", "correct": true, "because": "Bereichsleiter entscheiden"}, {"text": "Dezentrale Ressourcen", "correct": true, "because": "Unabhängige Mittel"}, {"text": "Zentrale Steuerung", "correct": false, "because": "Wenig Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass hier keine Spezialisierung nötig ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Bereiche spezialisiert"}, {"text": "Ja", "correct": false, "because": "Produktlinien fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für einen Bereich?', 3, '[{"text": "Bereichsziele", "correct": true, "because": "Produktlinie im Fokus"}, {"text": "Zentrale Vorgaben", "correct": false, "because": "Eigenständigkeit zählt"}, {"text": "Einheitliche Prozesse", "correct": false, "because": "Bereichsspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bereiche sind produktorientiert. b) Zentrale Teams entscheiden alles.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dezentral organisiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile könnten hier auftreten?', 5, '[{"text": "Wenig Koordination", "correct": true, "because": "Bereiche isoliert"}, {"text": "Doppelte Arbeit", "correct": true, "because": "Unterschiedliche Ansätze"}, {"text": "Hohe Zentralität", "correct": false, "because": "Dezentralisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Produktlinien", "correct": false, "because": "Basis der Struktur"}, {"text": "Eigenständigkeit", "correct": false, "because": "Kernprinzip"}, {"text": "Zentrale Abstimmung", "correct": true, "because": "Bereiche unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Bereiche hier zentral abhängig?', 3, '[{"text": "Nein", "correct": true, "because": "Eigenständig organisiert"}, {"text": "Ja", "correct": false, "because": "Dezentrale Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob hier alle Bereiche gleich arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Produktlinien unterschiedlich"}, {"text": "Ja", "correct": false, "because": "Bereichsspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle wähle ich für Bereichsstrategien?', 4, '[{"text": "Divisionsleiter", "correct": true, "because": "Führt den Bereich"}, {"text": "Zentrale Führung", "correct": false, "because": "Wenig direkter Einfluss"}, {"text": "Externer Berater", "correct": false, "because": "Bereichsintern"}]');
